-- ============================================================================
-- 00088_recipe_quantities — every dish gets amounts and a method (exact macros, P1).
-- GENERATED by web/scripts/buildRecipes.mjs from web/src/lib/food/recipes/*.js.
--
-- 00068 left quantities out on purpose: the plan's amounts were the planner's
-- shares of the basket. Exact macros need grams, so each line now names the
-- food it is (food.food_item) and how many grams ONE adult serving takes. The
-- engine scales servings to a person's numbers and rounds to kitchen measures;
-- these are the editorial base, not a prescription. Lines are matched in the
-- dish's own line order (the order dishData.js carries), never by a guessed
-- position. Steps are templates: {n} names line n (0-based) and {water:g}
-- names water, filled in at the servings being cooked.
-- ============================================================================

ALTER TABLE food.recipe_line
  ADD COLUMN IF NOT EXISTS food_key text REFERENCES food.food_item(key),
  ADD COLUMN IF NOT EXISTS grams_per_serving numeric(7,2) CHECK (grams_per_serving IS NULL OR grams_per_serving > 0);

ALTER TABLE food.dish
  ADD COLUMN IF NOT EXISTS served_grams smallint CHECK (served_grams IS NULL OR served_grams > 0),
  ADD COLUMN IF NOT EXISTS keeps_days smallint NOT NULL DEFAULT 0 CHECK (keeps_days BETWEEN 0 AND 7),
  ADD COLUMN IF NOT EXISTS batchable boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS recipe_version text;

CREATE TABLE IF NOT EXISTS food.recipe_step (
  dish_key      text NOT NULL REFERENCES food.dish(key) ON DELETE CASCADE,
  position      smallint NOT NULL CHECK (position > 0),
  title         text NOT NULL CHECK (btrim(title) <> ''),
  body          text NOT NULL CHECK (btrim(body) <> ''),
  minutes       smallint CHECK (minutes IS NULL OR minutes BETWEEN 0 AND 600),
  timer_seconds integer CHECK (timer_seconds IS NULL OR timer_seconds BETWEEN 1 AND 36000),
  PRIMARY KEY (dish_key, position)
);

COMMENT ON TABLE food.recipe_line IS 'What a dish is made of, where each part comes from, which food it is and the grams one adult serving takes (00088). The engine scales servings; these are the editorial base.';
COMMENT ON TABLE food.recipe_step IS 'A dish''s method. body is a template: {n} names recipe line n in line order (0-based), {water:g} names water; filled in at the servings being cooked.';

ALTER TABLE food.recipe_step ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON food.recipe_step FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON food.recipe_step TO service_role;

