UPDATE food.recipe_line r
SET food_key = a.food_key, grams_per_serving = a.grams
FROM ranked k JOIN amounts a ON a.dish_key = k.dish_key AND a.idx = k.idx
WHERE r.dish_key = k.dish_key AND r.position = k.position;

