INSERT INTO food.recipe_step (dish_key, position, title, body, minutes, timer_seconds) VALUES
  ('aam_panna', 1, 'Cook the mango', 'Boil {0} until soft, about 15 minutes. Cool, peel and squeeze out the pulp.', 18, 900),
  ('aam_panna', 2, 'Blend', 'Blend the pulp with {1}, {2}, roasted and crushed, {3} and {water:200}.', 3, NULL),
  ('aam_panna', 3, 'Serve', 'Pour it over ice with {4}.', 1, NULL),
  ('aloo_gobi', 1, 'Prepare', 'Cut {0} and {1} into bite-size pieces, and chop {2}.', 6, NULL),
  ('aloo_gobi', 2, 'Cook', 'Heat {5}. Add {3}; when it sizzles, add the potato and cook 5 minutes. Add the cauliflower, {4} and the salt.', 8, NULL),
  ('aloo_gobi', 3, 'Steam', 'Cover and cook on low for 12 minutes, stirring now and then, until both are tender. Add the tomato for the last 3 minutes.', 12, 720),
  ('aloo_matar', 1, 'Make the masala', 'Heat {7}. Add {5}, then {2}, chopped, and cook 4 minutes. Add {4}, grated, {3}, chopped, {6} and the salt; cook until soft.', 8, NULL),
  ('aloo_matar', 2, 'Add the vegetables', 'Add {0}, cubed, {1} and {water:200}.', 2, NULL),
  ('aloo_matar', 3, 'Simmer', 'Cover and simmer 15 minutes, until the potatoes are tender.', 15, 900),
  ('aloo_paratha', 1, 'Make the dough', 'Knead {0} with a pinch of the salt and about {water:50} into a soft dough. Cover it for 10 minutes.', 12, NULL),
  ('aloo_paratha', 2, 'Make the filling', 'Boil {1} until soft, about 15 minutes. Peel and mash with {2} and {3}, both finely chopped, and the rest of the salt.', 20, 900),
  ('aloo_paratha', 3, 'Roll and stuff', 'Divide the dough into 2 balls. Roll each into a small circle, put half the filling in the middle, pinch it shut and roll it out gently.', 8, NULL),
  ('aloo_paratha', 4, 'Cook', 'Cook each paratha on a hot tawa for a minute a side, then brush with {4} and cook until golden spots appear.', 8, 120),
  ('arbi_fry', 1, 'Boil', 'Boil {0} until a knife slides in, about 12 minutes. Peel and slice into rounds.', 15, 720),
  ('arbi_fry', 2, 'Season', 'Heat {3}. Add {1} and {2}, slit, then the arbi and the salt.', 2, NULL),
  ('arbi_fry', 3, 'Crisp', 'Fry on medium, turning, until golden at the edges, about 8 minutes.', 8, 480),
  ('avial', 1, 'Cook the vegetables', 'Cut {0}, {1}, {2} and {3} into finger-length sticks. Cook them with {water:120} and the salt, covered, for 10 minutes.', 12, 600),
  ('avial', 2, 'Grind the coconut', 'Grind {4} with {7} and a splash of water to a coarse paste.', 3, NULL),
  ('avial', 3, 'Bring it together', 'Stir the paste into the vegetables and cook 3 minutes. Take it off the heat and stir in {5}, whisked.', 4, NULL),
  ('avial', 4, 'Finish', 'Pour over {8} and add {6}.', 1, NULL),
  ('badam_milk', 1, 'Soak', 'Soak {1} in hot water for 15 minutes, then peel them.', 15, NULL),
  ('badam_milk', 2, 'Blend', 'Blend the almonds with a little of {0} to a smooth paste.', 2, NULL),
  ('badam_milk', 3, 'Simmer', 'Simmer the rest of the milk with the paste, {2}, crushed, and {3} for 5 minutes. Drink it warm or chilled.', 6, 300),
  ('baingan_bharta', 1, 'Roast', 'Roast {0} over a flame, turning, until the skin is black all over and it is soft inside, about 12 minutes.', 12, 720),
  ('baingan_bharta', 2, 'Peel and mash', 'Let it cool, peel off the skin and mash the flesh.', 5, NULL),
  ('baingan_bharta', 3, 'Cook', 'Heat {5}. Cook {3}, {4} and {1}, all chopped, for 4 minutes, then {2}, chopped, and the salt for 3 minutes. Stir in the brinjal and cook 5 minutes.', 12, NULL),
  ('bajra_roti', 1, 'Make the dough', 'Mix {0} and the salt with warm water, a little at a time, and knead with the heel of your hand until smooth.', 6, NULL),
  ('bajra_roti', 2, 'Shape', 'Pat small balls flat between wet palms, or on a floured board, into thick rounds.', 6, NULL),
  ('bajra_roti', 3, 'Cook', 'Cook on a hot tawa for 2 minutes a side, pressing the edges, until brown spots appear.', 8, 120),
  ('banana_peanut_butter', 1, 'Slice', 'Slice {0} into rounds.', 1, NULL),
  ('banana_peanut_butter', 2, 'Top', 'Spread or spoon {1} over them.', 1, NULL),
  ('banana_smoothie', 1, 'Blend', 'Blend {0}, {1}, {2} and {3} until smooth.', 2, NULL),
  ('banana_smoothie', 2, 'Serve', 'Drink it straight away.', 1, NULL),
  ('beans_poriyal', 1, 'Chop', 'Chop {0} finely.', 6, NULL),
  ('beans_poriyal', 2, 'Temper', 'Heat {5}. Add {2}; when they splutter, add {3} and {4}, slit.', 2, NULL),
  ('beans_poriyal', 3, 'Cook', 'Add the beans, the salt and {water:30}. Cover and cook 8 minutes, then stir in {1}.', 10, 480),
  ('besan_chilla', 1, 'Make the batter', 'Whisk {0} with {water:90} into a smooth, pourable batter. Stir in {5} and the salt.', 5, NULL),
  ('besan_chilla', 2, 'Add the vegetables', 'Finely chop {1}, {2}, {4} and {3}, and mix them into the batter.', 5, NULL),
  ('besan_chilla', 3, 'Cook', 'Brush a hot non-stick pan with a little oil ({6} in all). Pour in a ladle of batter, spread it thin and cook 2 minutes a side until golden. Repeat with the rest.', 10, 120),
  ('bhel_puri', 1, 'Prepare', 'Boil {3}, peel and dice it. Chop {1}, {2} and {7} finely.', 15, NULL),
  ('bhel_puri', 2, 'Mix', 'Just before eating, toss {0} with the vegetables, {4} loosened with a little water, {6} and the lemon.', 2, NULL),
  ('bhel_puri', 3, 'Finish', 'Scatter {5} on top and eat it straight away, before it softens.', 1, NULL),
  ('bhindi_masala', 1, 'Prepare', 'Wash {0} and dry it well, then cut into 1 cm pieces. Slice {1}.', 8, NULL),
  ('bhindi_masala', 2, 'Fry the okra', 'Heat {4}. Cook the okra on medium, uncovered, for 8 minutes until it is no longer sticky.', 8, 480),
  ('bhindi_masala', 3, 'Finish', 'Add the onion, {3}, chopped, {2} and the salt. Cook 5 minutes more.', 5, NULL),
