-- Every line of every dish must now have a food and grams; anything else means
-- the database's dishes drifted from dishData.js and the file must be rebuilt.
DO $$
DECLARE missing int;
BEGIN
  SELECT count(*) INTO missing FROM food.recipe_line WHERE food_key IS NULL OR grams_per_serving IS NULL;
  IF missing > 0 THEN
    RAISE EXCEPTION '00088: % recipe lines have no amount; dishData.js is out of step with food.recipe_line', missing;
  END IF;
END $$;
